/* MODULE kh06 · Bước 2 Hiểu khách hàng · Hành trình mua: từ lúc nghĩ tới đến lúc mua lại
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kh06', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kh06-01', skill:'insight', read:'6 phút', t:'Điều gì khiến khách bắt đầu nghĩ tới việc mua?',
  situation:'Bạn làm marketing cho một hãng máy lọc nước. Ngân sách quảng cáo chạy đều 12 tháng, nhưng doanh số dồn vào vài thời điểm: sau các bản tin về nước nhiễm bẩn, khi gia đình có em bé, và khi dọn về nhà mới. Sếp hỏi: có nên tiếp tục rải tiền đều mỗi tháng không?',
  concept:{ name:'Tác nhân kích hoạt (trigger)',
    body:'Hành trình mua không bắt đầu ở quảng cáo mà ở một <b>sự kiện trong đời khách</b> làm nhu cầu bật lên: có con, chuyển nhà, hỏng đồ cũ, lên lương, tin tức gây lo. Trước trigger, khách lướt qua quảng cáo vì chưa có lý do. Sau trigger, họ chủ động tìm. Hiểu trigger giúp bạn đặt tiền và thông điệp đúng lúc khách đang mở lòng, thay vì nói đều đều với người chưa cần.' },
  example:'Hãng xem lại 1.200 đơn năm ngoái: 420 đơn đến từ nhà mới, 300 đơn từ gia đình có em bé, 180 đơn trong hai tuần sau tin về nước bẩn, còn lại rải rác. Tức 75% đơn gắn với ba trigger. Hãng chuyển một phần ngân sách sang hợp tác với chủ đầu tư chung cư lúc bàn giao nhà và nhóm mẹ bầu, giữ một khoản dự phòng để bật nhanh khi có tin về chất lượng nước.',
  takeaway:'Khách không mua khi bạn quảng cáo; khách mua khi đời họ có chuyện. Hãy có mặt đúng lúc chuyện đó xảy ra.',
  apply:'Chọn một sản phẩm bạn dùng. Nói trong 60 giây: sự kiện nào khiến bạn bắt đầu tìm mua nó, và thương hiệu nào đã có mặt đúng lúc ấy.',
  mistakes:['Nghĩ nhu cầu có sẵn quanh năm nên rải ngân sách đều mọi tháng.','Chỉ nhắm theo nhân khẩu học mà bỏ qua sự kiện đang xảy ra trong đời khách.'],
  q:[
  { type:'mcq', stem:'Doanh số máy lọc nước dồn vào lúc chuyển nhà, có em bé và sau tin nước bẩn. Đoán xem vì sao?',
    options:[{k:'a',t:'Đó là lúc các hãng đồng loạt giảm giá sâu nên khách tranh thủ mua'},{k:'b',t:'Các sự kiện đó làm nhu cầu bật lên, khách bắt đầu chủ động tìm'},
             {k:'c',t:'Quảng cáo cả năm dồn lại tới lúc đó mới đủ tần suất để khách nhớ'},{k:'d',t:'Người có em bé và người mua nhà thường có thu nhập cao hơn'}],
    answer:'b', why:{a:'Không có dữ kiện về giảm giá; đơn dồn theo sự kiện đời sống chứ không theo lịch khuyến mãi.',
      b:'Đúng. Đó là các trigger: trước đó khách chưa có lý do, sau đó họ tự đi tìm.',
      c:'Tần suất quảng cáo tích luỹ không giải thích vì sao đơn tăng ngay sau một bản tin.',
      d:'Thu nhập có thể liên quan, nhưng thu nhập không đổi đột ngột trong hai tuần sau bản tin.'} },
  { type:'mcq', stem:'Sếp hỏi có nên giữ ngân sách rải đều 12 tháng. Bạn đề xuất gì?',
    options:[{k:'a',t:'Giữ rải đều vì khách có thể phát sinh nhu cầu bất kỳ lúc nào trong năm'},{k:'b',t:'Dồn hết ngân sách vào một đợt lớn đầu năm để tạo độ phủ thật mạnh'},
             {k:'c',t:'Cắt hẳn quảng cáo, chỉ chờ có tin nước bẩn rồi mới chạy'},{k:'d',t:'Dời phần lớn tiền sang nơi trigger xảy ra, giữ khoản dự phòng bật nhanh'}],
    answer:'d', why:{a:'Rải đều nghĩa là phần lớn tiền nói với người chưa cần.',
      b:'Đầu năm không trùng với lúc khách chuyển nhà hay có con.',
      c:'Chỉ chờ tin tức bỏ lỡ hai trigger lớn và ổn định hơn: nhà mới và em bé.',
      d:'Đúng. Có mặt ở điểm bàn giao nhà, nhóm mẹ bầu, và sẵn sàng khi có tin nóng.'} },
  { type:'calc', stem:'Trong 1.200 đơn, 420 đến từ nhà mới, 300 từ gia đình có em bé, 180 sau tin nước bẩn. Ba trigger chiếm bao nhiêu phần trăm số đơn?',
    unit:'%', ans:75, tol:0.1, wrong:[[35,'SAI_MAU_SO'],[900,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Cộng đơn của ba trigger: 420 + 300 + 180 = 900.','Chia cho tổng đơn: 900 ÷ 1.200 = <b>75%</b>.'] },
  { type:'mcq', stem:'Một chuỗi nội thất muốn tìm khách đúng lúc. Trigger nào đáng theo dõi nhất?',
    options:[{k:'a',t:'Người vừa nhận bàn giao căn hộ hoặc vừa ký hợp đồng thuê nhà'},{k:'b',t:'Người trong độ tuổi 25–40 sống ở thành phố lớn và có thu nhập khá'},
             {k:'c',t:'Người đã like trang của chuỗi từ vài năm trước nhưng chưa từng mua'},{k:'d',t:'Người hay xem video trang trí nhà cửa vì thấy đẹp mắt, giải trí'}],
    answer:'a', why:{a:'Đúng. Nhận nhà là sự kiện buộc khách phải mua đồ trong vài tuần.',
      b:'Đó là chân dung nhân khẩu học, không cho biết ai đang cần mua ngay.',
      c:'Like cũ không phải sự kiện; nhu cầu có thể đã qua hoặc chưa tới.',
      d:'Xem giải trí khác với có lý do mua; nhiều người xem cho vui cả năm.'} },
  { type:'mcq', stem:'Vì sao thông điệp nên khác nhau cho người trước và sau trigger?',
    options:[{k:'a',t:'Vì người trước trigger cần được giảm giá mạnh hơn mới chịu nghe'},{k:'b',t:'Vì nền tảng quảng cáo tính giá khác nhau cho hai nhóm người này'},
             {k:'c',t:'Người sau trigger đang tìm cách giải quyết; người trước chỉ cần nhớ tên'},{k:'d',t:'Vì người sau trigger đã quyết xong nên không cần thông tin gì thêm'}],
    answer:'c', why:{a:'Giảm giá không tạo ra lý do mua khi đời khách chưa có chuyện.',
      b:'Giá thầu có thể khác, nhưng đó không phải lý do đổi nội dung thông điệp.',
      c:'Đúng. Sau trigger khách cần so sánh, cần lý do chọn; trước đó chỉ cần gieo trí nhớ.',
      d:'Sau trigger khách mới bắt đầu tìm hiểu, chưa quyết gì cả.'} },
  { type:'mcq', stem:'Hãng điều hoà thấy đơn tăng vọt trong đợt nắng nóng đầu tháng 4. Nên hiểu trigger ở đây thế nào?',
    options:[{k:'a',t:'Đợt nóng đầu tiên làm máy cũ lộ yếu và khiến khách thấy không thể chờ'},{k:'b',t:'Tháng 4 là mùa thưởng nên ai cũng có tiền mua đồ điện máy lớn'},
             {k:'c',t:'Khách được nhắc nhiều lần qua quảng cáo tháng 3 nên tới tháng 4 mới mua'},{k:'d',t:'Đơn tăng vì các cửa hàng bắt đầu trưng điều hoà ra phía trước'}],
    answer:'a', why:{a:'Đúng. Cái nóng là sự kiện làm nhu cầu bật lên gấp; nhiều khách cần lắp trong tuần.',
      b:'Mùa thưởng thường quanh Tết, không giải thích đỉnh theo đợt nóng.',
      c:'Nếu vậy đơn sẽ tăng dần, không vọt theo đúng ngày nhiệt độ tăng.',
      d:'Trưng bày là phản ứng của cửa hàng với nhu cầu, không phải nguyên nhân gốc.'} },
  { type:'mcq', stem:'Một bạn đề xuất nhắm quảng cáo sữa bột cho "phụ nữ 25–35 tuổi". Góp ý có căn cứ nhất là gì?',
    options:[{k:'a',t:'Nên mở rộng ra 18–45 tuổi để có tệp lớn hơn và giá thấp hơn'},{k:'b',t:'Nên đổi sang nhắm theo sở thích nấu ăn vì liên quan chuyện chăm con'},
             {k:'c',t:'Nên nhắm cả nam giới vì các ông bố cũng tham gia quyết định mua'},{k:'d',t:'Nên nhắm theo sự kiện: đang mang thai, sắp sinh, con sắp cai sữa'}],
    answer:'d', why:{a:'Tệp to hơn chỉ làm loãng thêm; phần lớn vẫn chưa có con nhỏ.',
      b:'Sở thích nấu ăn không nói ai đang cần sữa bột.',
      c:'Bố có tham gia, nhưng vấn đề gốc là nhắm theo tuổi thay vì theo sự kiện.',
      d:'Đúng. Sữa bột gắn với các mốc của con; tuổi mẹ chỉ là đại diện rất lỏng.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kh06-02', skill:'insight', read:'7 phút', t:'Khách so sánh những ai trước khi chọn bạn?',
  situation:'Một hãng nồi chiên không dầu mới ra mắt, giá 1,9 triệu. Đội marketing chỉ theo dõi hai đối thủ cùng tầm giá. Nhưng khi phỏng vấn 30 người vừa mua, nhiều người kể họ còn cân nhắc lò nướng mini, nồi đa năng và thậm chí mua hàng cũ trên nhóm Facebook.',
  concept:{ name:'Tập cân nhắc (consideration set)',
    body:'Khi đã có nhu cầu, khách không xét mọi lựa chọn trên thị trường. Họ gom vài cái tên vào một <b>danh sách ngắn</b>, thường 2–4 lựa chọn, rồi so trong đó. Danh sách này được lập từ trí nhớ, lời bạn bè, kết quả tìm kiếm, review. Điều quan trọng: đối thủ thật là những gì nằm trong danh sách của khách, không phải những gì bạn xếp cùng ngành. Nếu không lọt vào danh sách, quảng cáo hay giá tốt cũng không có dịp phát huy.' },
  example:'Trong 30 người phỏng vấn, 22 người có lò nướng mini trong danh sách, 14 người có nồi đa năng, 9 người xem hàng cũ, chỉ 12 người nhắc tới đối thủ mà đội đang theo dõi. Hãng nhận ra câu hỏi khách tự đặt là "nồi chiên hay lò nướng?" chứ không phải "hãng A hay hãng B?". Nội dung mới tập trung so nồi chiên với lò nướng: nhanh hơn, ít vệ sinh hơn, hợp bếp chung cư.',
  takeaway:'Đối thủ của bạn là những gì khách đặt cạnh bạn trong đầu, không phải những gì bạn xếp cùng ngành.',
  apply:'Hỏi hai người quen vừa mua một món đồ: "Trước khi chọn, bạn còn xem những gì?". Nói trong 60 giây danh sách đó có gì bất ngờ.',
  mistakes:['Chỉ theo dõi đối thủ cùng ngành, cùng tầm giá.','Nghĩ khách so sánh mọi lựa chọn trên thị trường rồi mới chọn.'],
  q:[
  { type:'mcq', stem:'Khách mua nồi chiên kể họ còn cân nhắc lò nướng mini và hàng cũ. Đoán xem điều này nói gì?',
    options:[{k:'a',t:'Khách chưa hiểu sản phẩm nên cần giáo dục lại thị trường từ đầu'},{k:'b',t:'Lò nướng và hàng cũ chỉ là lựa chọn phụ, không đáng để theo dõi'},
             {k:'c',t:'Đối thủ thật trong đầu khách rộng hơn danh sách đội đang theo dõi'},{k:'d',t:'Mẫu phỏng vấn 30 người quá nhỏ để rút ra bất cứ kết luận nào'}],
    answer:'c', why:{a:'Khách hiểu rõ nhu cầu nấu nướng; họ chỉ xét nhiều cách giải quyết.',
      b:'22/30 người xét lò nướng — đó là đối thủ chính chứ không phải phụ.',
      c:'Đúng. Tập cân nhắc của khách vượt ra khỏi ranh giới ngành mà đội tự vẽ.',
      d:'30 người không đo được tỉ lệ chính xác, nhưng đủ để phát hiện đối thủ bị bỏ sót.'} },
  { type:'mcq', stem:'Biết 22/30 khách so nồi chiên với lò nướng, bạn chọn làm gì với nội dung?',
    options:[{k:'a',t:'Làm nội dung trả lời thẳng "nồi chiên hay lò nướng" cho bếp chung cư'},{k:'b',t:'Tăng ngân sách so sánh tính năng chi tiết với hai hãng nồi chiên cùng giá'},
             {k:'c',t:'Giảm giá xuống thấp hơn lò nướng mini để thắng ngay về giá'},{k:'d',t:'Ra thêm một dòng lò nướng để có mặt ở cả hai lựa chọn của khách'}],
    answer:'a', why:{a:'Đúng. Trả lời đúng câu hỏi khách đang tự đặt giúp bạn thắng ở vòng so sánh thật.',
      b:'Chỉ 12/30 khách xét hai hãng đó; bạn đang trả lời câu hỏi ít người hỏi.',
      c:'Giảm giá không giải thích vì sao nồi chiên hợp hơn, lại làm mỏng lãi.',
      d:'Ra sản phẩm mới là quyết định lớn, không phải phản ứng đầu tiên với một phát hiện nội dung.'} },
  { type:'calc', stem:'Trong 30 người phỏng vấn, 12 người nhắc tới đối thủ cùng ngành mà đội đang theo dõi. Tỉ lệ này là bao nhiêu phần trăm?',
    unit:'%', ans:40, tol:0.1, wrong:[[250,'SAI_MAU_SO'],[12,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ = số người nhắc ÷ tổng số người.','12 ÷ 30 = 0,4 = <b>40%</b>.'] },
  { type:'mcq', stem:'Một quán cà phê mới thấy khách văn phòng gần đó vẫn mang cà phê pha phin từ nhà. Đối thủ thật của quán gồm gì?',
    options:[{k:'a',t:'Chỉ các chuỗi cà phê lớn trong bán kính 500 mét quanh quán'},{k:'b',t:'Cả thói quen tự pha ở nhà, không riêng các quán cà phê gần đó'},
             {k:'c',t:'Các quán trà sữa vì cùng nhắm tới nhóm khách văn phòng trẻ'},{k:'d',t:'Chỉ những quán có giá ngang hoặc rẻ hơn mức giá của quán mình'}],
    answer:'b', why:{a:'Chuỗi lớn có trong danh sách, nhưng bỏ qua lựa chọn phổ biến nhất: tự pha.',
      b:'Đúng. Với nhiều khách, câu hỏi là "mua hay tự pha", nên tự pha là đối thủ.',
      c:'Trà sữa có thể là đối thủ, nhưng dữ kiện cho thấy thói quen tự pha mới là thứ đang giữ khách.',
      d:'Giá chỉ là một tiêu chí; khách không lập danh sách theo đúng mức giá của bạn.'} },
  { type:'mcq', stem:'Vì sao lọt vào tập cân nhắc lại quan trọng hơn thắng một so sánh tính năng?',
    options:[{k:'a',t:'Vì khách thường mua lựa chọn đầu tiên họ nghĩ tới, không so gì cả'},{k:'b',t:'Vì so sánh tính năng chỉ có tác dụng với hàng công nghệ đắt tiền'},
             {k:'c',t:'Vì nền tảng quảng cáo ưu tiên thương hiệu đã có sẵn trong trí nhớ'},{k:'d',t:'Vì không có trong danh sách thì khách không bao giờ so tới bạn'}],
    answer:'d', why:{a:'Khách có so sánh, nhưng chỉ trong danh sách ngắn của họ.',
      b:'So sánh tính năng có tác dụng ở nhiều ngành; vấn đề là phải được so trước đã.',
      c:'Nền tảng không đọc trí nhớ khách; đó là hiểu lầm về cơ chế.',
      d:'Đúng. Ưu điểm tốt đến mấy cũng vô ích nếu khách không mang bạn ra so.'} },
  { type:'mcq', stem:'Hãng muốn biết mình có nằm trong danh sách của khách hay không. Cách kiểm tra nào hợp lý nhất?',
    options:[{k:'a',t:'Đếm lượt thích và chia sẻ trên trang fanpage chính của hãng'},{k:'b',t:'Hỏi người vừa mua trong ngành: "Bạn đã xem những lựa chọn nào?"'},
             {k:'c',t:'So doanh số của hãng với hai đối thủ cùng tầm giá theo từng tháng'},{k:'d',t:'Xem báo cáo thị phần ngành do một công ty nghiên cứu công bố hằng năm'}],
    answer:'b', why:{a:'Lượt thích đo mức tương tác, không cho biết lúc mua khách có xét bạn không.',
      b:'Đúng. Hỏi người vừa mua cho thấy trực tiếp danh sách ngắn của họ.',
      c:'Doanh số là kết quả cuối, không tách được lỗi "không được xét" với lỗi "bị loại".',
      d:'Thị phần cho biết ai bán nhiều, không cho biết khách đã so những ai.'} },
  { type:'mcq', stem:'Một hãng sữa hạt thấy khách so mình với sữa tươi chứ không phải hãng sữa hạt khác. Nên sửa gì trước?',
    options:[{k:'a',t:'Hạ giá cho bằng các hãng sữa hạt khác để cạnh tranh trực diện'},{k:'b',t:'In thêm bảng dinh dưỡng chi tiết để hơn hẳn các hãng sữa hạt'},
             {k:'c',t:'Nói rõ lý do chọn sữa hạt thay sữa tươi: nhẹ bụng, hợp người kiêng'},{k:'d',t:'Tài trợ sự kiện chạy bộ để tăng độ nhận biết thương hiệu nói chung'}],
    answer:'c', why:{a:'Khách không so với hãng sữa hạt khác, nên cạnh tranh giá với họ là trượt mục tiêu.',
      b:'Hơn hãng sữa hạt khác không giúp thắng câu hỏi "sữa hạt hay sữa tươi".',
      c:'Đúng. Trả lời đúng cuộc so sánh mà khách đang thực sự làm.',
      d:'Nhận biết chung không giải quyết câu hỏi cụ thể trong đầu khách.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kh06-03', skill:'channel', read:'7 phút', t:'Khách xem trên TikTok, hỏi Zalo, mua ở cửa hàng — tính công cho ai?',
  situation:'Một chuỗi mỹ phẩm có cả cửa hàng và kênh online. Chị Hà thấy video review trên TikTok, vào Shopee đọc đánh giá, nhắn Zalo cửa hàng hỏi còn hàng không, rồi ghé chi nhánh gần nhà để thử và mua. Báo cáo cuối tháng ghi đơn này là "doanh số cửa hàng", còn TikTok bị đánh giá là không ra đơn.',
  concept:{ name:'Điểm chạm đan xen online – offline',
    body:'Một hành trình mua thường đi qua nhiều <b>điểm chạm</b>: video, sàn, tin nhắn, cửa hàng, lời bạn bè. Khách không đi theo một kênh; họ nhảy qua lại tuỳ lúc tiện. Báo cáo theo kênh thì chỉ ghi nơi thanh toán, nên các kênh ở đầu hành trình dễ bị xem là vô dụng. Muốn quyết định đúng, cần vẽ lại chuỗi điểm chạm của khách thật và hỏi: bỏ một điểm chạm thì hành trình có còn đi tới cuối không?' },
  example:'Chuỗi hỏi 50 khách mua tại cửa hàng: 31 người kể đã xem sản phẩm trên mạng trước khi đến, trong đó 18 người nhắn Zalo hỏi hàng. Như vậy 62% đơn "cửa hàng" có bước online phía trước. Chuỗi không cắt TikTok nữa; thay vào đó thêm dòng "còn hàng ở chi nhánh nào" vào cuối video, và bố trí người trả lời Zalo trong 5 phút giờ cao điểm.',
  takeaway:'Nơi khách trả tiền chỉ là điểm chạm cuối; đừng cắt những bước đã đưa khách tới đó.',
  apply:'Nhớ lại lần mua gần nhất của bạn. Kể trong 60 giây mọi chỗ bạn đã chạm vào thương hiệu trước khi trả tiền.',
  mistakes:['Tính toàn bộ công cho kênh nơi khách thanh toán.','Cắt kênh ở đầu hành trình vì báo cáo ghi "không ra đơn".'],
  q:[
  { type:'mcq', stem:'Báo cáo ghi TikTok không ra đơn, nhưng khách kể xem TikTok rồi mới đến cửa hàng. Đoán xem vấn đề ở đâu?',
    options:[{k:'a',t:'Khách nhớ sai, vì người ta thường kể lại hành trình theo cảm tính'},{k:'b',t:'Video TikTok chưa gắn link mua hàng nên không thể ra đơn được'},
             {k:'c',t:'TikTok chỉ tạo độ nhận biết, không bao giờ góp vào quyết định mua'},{k:'d',t:'Báo cáo chỉ ghi nơi thanh toán, bỏ qua bước đã dẫn khách tới'}],
    answer:'d', why:{a:'Có thể nhớ sai vài chi tiết, nhưng 31/50 người cùng kể là một khuôn mẫu.',
      b:'Gắn link giúp đo, nhưng khách vẫn thích thử tại cửa hàng; thiếu link không có nghĩa không có tác dụng.',
      c:'Dữ kiện cho thấy video là bước đầu của hành trình dẫn tới mua.',
      d:'Đúng. Báo cáo theo kênh thanh toán làm các điểm chạm đầu hành trình trở nên vô hình.'} },
  { type:'mcq', stem:'Sếp đề nghị cắt ngân sách TikTok vì "không ra đơn". Bạn đề xuất gì?',
    options:[{k:'a',t:'Đồng ý cắt, dồn tiền vào khuyến mãi tại cửa hàng vì ở đó ra đơn'},{k:'b',t:'Giữ TikTok, nối nó với bước sau: ghi rõ chi nhánh còn hàng, trả lời Zalo nhanh'},
             {k:'c',t:'Chuyển toàn bộ sang bán trực tiếp trên TikTok Shop để đo đơn cho dễ'},{k:'d',t:'Giữ nguyên mọi thứ và chờ thêm ba tháng số liệu rồi mới bàn tiếp'}],
    answer:'b', why:{a:'Cắt TikTok có thể làm hụt 62% khách đang được dẫn tới cửa hàng.',
      b:'Đúng. Giữ bước đầu và làm cầu nối sang bước sau chắc hơn.',
      c:'Nhiều khách mỹ phẩm muốn thử trước khi mua; ép họ mua online có thể mất đơn.',
      d:'Chờ thêm không sửa được cách báo cáo sai; bạn đã có dữ kiện để hành động.'} },
  { type:'calc', stem:'Hỏi 50 khách mua tại cửa hàng, 31 người đã xem sản phẩm trên mạng trước khi đến. Tỉ lệ đơn "cửa hàng" có bước online phía trước là bao nhiêu phần trăm?',
    unit:'%', ans:62, tol:0.1, wrong:[[36,'SAI_MAU_SO'],[161.3,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = khách có bước online ÷ tổng khách được hỏi.','31 ÷ 50 = <b>62%</b>.'] },
  { type:'mcq', stem:'Khách hỏi Zalo "chi nhánh Quận 7 còn màu số 03 không?" và phải chờ 3 tiếng mới được trả lời. Rủi ro lớn nhất là gì?',
    options:[{k:'a',t:'Khách quên mất câu hỏi và đổi ý không mua thứ gì cả'},{k:'b',t:'Khách sẽ viết đánh giá một sao trên trang Google Maps của cửa hàng'},
             {k:'c',t:'Khách chuyển sang hỏi hãng khác hoặc mua ngay trên sàn'},{k:'d',t:'Khách vẫn tới cửa hàng như dự định nên việc chờ không sao cả'}],
    answer:'c', why:{a:'Nhu cầu vẫn còn; chỉ là nó chảy sang nơi trả lời nhanh hơn.',
      b:'Có thể xảy ra nhưng ít hơn việc lặng lẽ mua chỗ khác.',
      c:'Đúng. Điểm chạm chậm là chỗ hành trình bị cắt, khách rời sang lựa chọn khác.',
      d:'Khách hỏi vì chưa chắc có hàng; không có câu trả lời thì họ ngại đi.'} },
  { type:'mcq', stem:'Một cửa hàng xe máy muốn biết khách đã chạm những đâu trước khi tới. Cách nào tốn ít mà hiệu quả?',
    options:[{k:'a',t:'Chạy thêm quảng cáo có mã giảm giá riêng cho từng kênh và đếm mã'},{k:'b',t:'Mua phần mềm phân bổ đa kênh đắt tiền và gắn cho mọi điểm chạm'},
             {k:'c',t:'Dựa vào lượt xem video để đoán kênh nào đã dẫn khách tới'},{k:'d',t:'Khi chốt đơn, nhân viên hỏi một câu: "Anh chị biết xe này qua đâu?"'}],
    answer:'d', why:{a:'Mã giảm giá đo được phần nào nhưng tốn chi phí khuyến mãi và làm lệch hành vi.',
      b:'Phần mềm đắt và khó gắn cho lời bạn bè hay lần đi ngang cửa hàng.',
      c:'Lượt xem không nói ai trong số đó đã tới mua.',
      d:'Đúng. Một câu hỏi tại quầy cho dữ kiện trực tiếp, gần như miễn phí.'} },
  { type:'mcq', stem:'Vì sao "tính công hết cho kênh cuối" hay dẫn tới quyết định sai?',
    options:[{k:'a',t:'Vì kênh cuối thường là kênh rẻ nhất nên số liệu luôn đẹp hơn thực tế'},{k:'b',t:'Vì nó thưởng bước chốt và phạt các bước đã tạo ra nhu cầu phía trước'},
             {k:'c',t:'Vì kênh cuối hay bị nền tảng quảng cáo đếm trùng đơn nhiều lần'},{k:'d',t:'Vì khách luôn quyết định ở bước đầu tiên, còn kênh cuối chỉ là thủ tục'}],
    answer:'b', why:{a:'Kênh cuối không nhất thiết rẻ; vấn đề là cách chia công.',
      b:'Đúng. Cắt bước đầu vì "không ra đơn" có thể làm cạn dòng khách về sau.',
      c:'Đếm trùng là vấn đề khác, không phải lý do chính.',
      d:'Quyết định hình thành dần qua nhiều bước, không chốt hẳn ở bước đầu.'} },
  { type:'mcq', stem:'Chuỗi thấy khách đọc đánh giá trên Shopee rồi ra cửa hàng mua. Nên làm gì với trang Shopee?',
    options:[{k:'a',t:'Gỡ trang Shopee để khách buộc phải ra cửa hàng mua trực tiếp'},{k:'b',t:'Giảm giá sâu trên Shopee để khách chuyển hết sang mua online'},
             {k:'c',t:'Chăm đánh giá và ghi rõ "có thể thử tại chi nhánh" ngay trên trang'},{k:'d',t:'Bỏ mặc vì Shopee không ra đơn cho cửa hàng trong báo cáo tháng'}],
    answer:'c', why:{a:'Gỡ trang là mất chỗ khách đang dùng để kiểm tra độ tin cậy.',
      b:'Giảm giá sâu làm mỏng lãi và phá giá ở cửa hàng.',
      c:'Đúng. Trang sàn đang là bước "kiểm tra" trong hành trình; làm nó tốt và nối sang cửa hàng.',
      d:'Chính vì báo cáo bỏ sót nên càng không được bỏ mặc điểm chạm này.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kh06-04', skill:'channel', read:'6 phút', t:'Khách đã chọn hãng bạn ở nhà, sao đến cửa hàng lại đổi ý?',
  situation:'Một hãng dầu gội đầu tư mạnh cho quảng cáo, khảo sát cho thấy nhiều người định mua. Nhưng ở siêu thị, nhân viên quan sát thấy khách cầm chai của hãng lên, nhìn giá, rồi đặt xuống lấy chai bên cạnh đang có gắn tem "mua 1 tặng 1" và được bày ngang tầm mắt.',
  concept:{ name:'Khoảnh khắc quyết định tại điểm bán',
    body:'Nhiều ngành hàng tiêu dùng nhanh được chọn ngay trước kệ trong vài giây. Ý định mang từ nhà dễ bị lật bởi <b>những gì khách thấy tại chỗ</b>: vị trí trên kệ, tem khuyến mãi, bao bì dễ nhận ra, giá so với chai bên cạnh, lời tư vấn. Đây là điểm cuối của hành trình nhưng lại là nơi dễ mất khách nhất, vì mọi đối thủ đang đứng sát nhau. Làm tốt ở nhà mà bỏ trống điểm bán là để người khác chốt đơn hộ.' },
  example:'Nhân viên đếm tại 4 siêu thị: 200 khách cầm chai của hãng lên, 70 người đặt xuống và lấy hãng khác. Tức 35% khách đã có ý định bị mất ngay trước kệ. Hãng không tăng quảng cáo TV; thay vào đó đổi vị trí lên ngang tầm mắt, làm dải kệ cùng màu để dễ tìm, và in lợi ích chính to trên mặt trước thay vì chỉ có tên.',
  takeaway:'Ý định mua mang từ nhà không bảo đảm; vài giây trước kệ mới là nơi đơn hàng được chốt.',
  apply:'Đứng 10 phút ở một kệ hàng. Nói trong 60 giây: bạn thấy bao nhiêu người cầm lên rồi đặt xuống, và điều gì có vẻ khiến họ đổi.',
  mistakes:['Nghĩ khách đã có ý định từ quảng cáo thì chắc chắn sẽ mua.','Dồn hết tiền cho quảng cáo, để điểm bán tuỳ siêu thị bày.'],
  q:[
  { type:'mcq', stem:'Khách định mua dầu gội hãng A nhưng tới kệ lại lấy hãng B. Đoán xem yếu tố nào hay lật quyết định nhất?',
    options:[{k:'a',t:'Những gì khách thấy tại chỗ: vị trí, khuyến mãi, giá kề bên'},{k:'b',t:'Quảng cáo của hãng A trên TV chưa đủ nhiều lần nên khách chưa nhớ'},
             {k:'c',t:'Khách đổi ý vì đọc được một review xấu về hãng A trên đường đi'},{k:'d',t:'Hãng B có thành phần tốt hơn mà khách phát hiện khi đọc nhãn sau'}],
    answer:'a', why:{a:'Đúng. Trước kệ, tín hiệu tại chỗ thường mạnh hơn trí nhớ quảng cáo.',
      b:'Khách đã nhớ và đã cầm chai của A lên; vấn đề không ở trí nhớ.',
      c:'Có thể xảy ra nhưng không phải khuôn mẫu phổ biến trong dữ kiện.',
      d:'Khách chỉ nhìn giá vài giây, ít ai đọc kỹ thành phần trước kệ.'} },
  { type:'mcq', stem:'35% khách cầm chai rồi đặt xuống. Với ngân sách có hạn, bạn ưu tiên sửa gì?',
    options:[{k:'a',t:'Tăng tần suất quảng cáo TV lên gấp đôi để khách nhớ thương hiệu hơn'},{k:'b',t:'Chạy thêm chiến dịch KOL để khách tin sản phẩm hơn khi ở nhà'},
             {k:'c',t:'Giảm giá sâu cho bằng hãng bên cạnh trong suốt cả năm'},{k:'d',t:'Sửa điểm bán: vị trí ngang tầm mắt, mặt trước ghi rõ lợi ích chính'}],
    answer:'d', why:{a:'Khách đã nhớ đủ để cầm chai lên; vấn đề nằm ở vài giây tiếp theo.',
      b:'KOL tác động trước khi tới kệ, không sửa điều khách thấy tại kệ.',
      c:'Giảm giá quanh năm làm mỏng lãi và dạy khách chỉ mua khi rẻ.',
      d:'Đúng. Mất khách ở kệ thì sửa ở kệ, rẻ hơn mua thêm nhận biết.'} },
  { type:'calc', stem:'Tại 4 siêu thị, 200 khách cầm chai của hãng lên và 70 người đặt xuống lấy hãng khác. Tỉ lệ khách bị mất trước kệ là bao nhiêu phần trăm?',
    unit:'%', ans:35, tol:0.1, wrong:[[65,'NHAM_TI_LE_ROI'],[285.7,'SAI_MAU_SO']], errors:['NHAM_TI_LE_ROI','SAI_MAU_SO'],
    steps:['Tỉ lệ mất = số người đặt xuống ÷ số người cầm lên.','70 ÷ 200 = <b>35%</b>.'] },
  { type:'mcq', stem:'Một hãng bánh kẹo thấy khách mua theo kiểu "nhìn thấy mới nhớ". Khoảnh khắc nào đáng đầu tư nhất?',
    options:[{k:'a',t:'Quảng cáo buổi tối lúc cả nhà cùng ngồi xem truyền hình'},{k:'b',t:'Quầy thanh toán và kệ đầu lối đi, nơi khách thấy ngay khi chờ'},
             {k:'c',t:'Bài đăng trên fanpage vào dịp lễ để tăng lượt tương tác'},{k:'d',t:'Email giới thiệu sản phẩm mới gửi tới toàn bộ hội viên'}],
    answer:'b', why:{a:'Xem TV ở nhà cách xa lúc mua; với hàng mua bốc đồng thì tác động yếu.',
      b:'Đúng. Hàng mua bốc đồng cần xuất hiện đúng chỗ khách đang đứng chờ.',
      c:'Tương tác trên fanpage không đặt sản phẩm trước mắt khách lúc có thể mua.',
      d:'Email tới lúc khách không ở gần kệ hàng.'} },
  { type:'mcq', stem:'Vì sao bao bì chỉ in tên thương hiệu thật to lại có thể thua tại kệ?',
    options:[{k:'a',t:'Vì tên to làm bao bì trông rẻ tiền và kém sang trọng hơn đối thủ'},{k:'b',t:'Vì siêu thị hạn chế bao bì có chữ quá lớn trên kệ trưng bày'},
             {k:'c',t:'Vì khách chỉ có vài giây, cần thấy ngay lợi ích để chọn'},{k:'d',t:'Vì tên to khiến khách tưởng là hàng khuyến mãi sắp hết hạn'}],
    answer:'c', why:{a:'Sang hay rẻ là chuyện thẩm mỹ, không phải lý do chính gây thua.',
      b:'Không có quy định kiểu này; đó là hiểu lầm.',
      c:'Đúng. Tên giúp nhận ra, nhưng lợi ích giúp chọn trong khoảnh khắc so sánh.',
      d:'Không có liên hệ giữa cỡ chữ và cảm giác hàng sắp hết hạn.'} },
  { type:'mcq', stem:'Một cửa hàng điện thoại thấy khách hay đổi hãng sau khi nói chuyện với nhân viên. Nên hiểu thế nào?',
    options:[{k:'a',t:'Nhân viên tư vấn là một điểm chạm quyết định tại điểm bán'},{k:'b',t:'Khách chưa tìm hiểu kỹ ở nhà nên dễ bị thuyết phục qua loa'},
             {k:'c',t:'Hãng nên cấm nhân viên cửa hàng nói về các hãng đối thủ'},{k:'d',t:'Cần thêm quảng cáo online để khách chắc chắn trước khi tới'}],
    answer:'a', why:{a:'Đúng. Với hàng đắt, lời người tư vấn tại chỗ có sức nặng lớn; hãng cần đào tạo và hỗ trợ nhân viên.',
      b:'Nhiều khách đã tìm hiểu kỹ, vẫn đổi vì lời tư vấn đáng tin tại chỗ.',
      c:'Cửa hàng đa hãng không phải của bạn; cấm là không khả thi.',
      d:'Thêm quảng cáo không làm mất sức nặng của người đang đứng cạnh khách.'} },
  { type:'mcq', stem:'Hãng chỉ đủ tiền làm một việc ở 4 siêu thị thử nghiệm. Cách chọn việc nào có căn cứ nhất?',
    options:[{k:'a',t:'Làm theo đúng cách đối thủ lớn đang làm vì họ đã thử trước rồi'},{k:'b',t:'Chọn việc đẹp nhất theo ý kiến của phòng thiết kế bao bì trong hãng'},
             {k:'c',t:'Làm ở tất cả siêu thị cùng lúc để có kết quả nhanh và rõ hơn'},{k:'d',t:'Đổi một thứ ở 2 siêu thị, giữ 2 siêu thị so sánh, rồi đếm lại'}],
    answer:'d', why:{a:'Đối thủ có vị thế khác; sao chép không cho biết điều gì hợp với bạn.',
      b:'Ý kiến nội bộ không thay được hành vi khách tại kệ.',
      c:'Đổi mọi nơi cùng lúc thì không có nhóm so sánh để biết thay đổi có tác dụng không.',
      d:'Đúng. Có nhóm so sánh mới biết tỉ lệ đặt xuống giảm nhờ thay đổi nào.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kh06-05', skill:'brand', read:'6 phút', t:'Mua xong rồi, sao vẫn cần lo lần mở hộp và lần dùng đầu?',
  situation:'Một shop tai nghe bán online, đơn đầu mỗi tháng khoảng 800. Hàng tốt nhưng tỉ lệ trả hàng cao: khách phàn nàn "không kết nối được", "đeo không vừa". Kiểm tra lại thì phần lớn là do khách không biết bấm giữ nút để ghép đôi và không biết trong hộp có sẵn nút tai cỡ khác.',
  concept:{ name:'Trải nghiệm mở hộp và lần dùng đầu',
    body:'Hành trình không kết thúc khi khách trả tiền. <b>Lần mở hộp và lần dùng đầu</b> là lúc khách kiểm chứng lời hứa. Nếu lần đầu trục trặc, khách đổ lỗi cho sản phẩm dù lỗi nằm ở hướng dẫn. Việc cần làm: tìm các bước khách hay vấp trong 10 phút đầu, rồi đặt lời giải ngay chỗ họ vấp — một tấm thẻ trên cùng, một mã QR dẫn tới video 30 giây, nút tai cỡ khác gắn kèm hình. Làm tốt ở đây rẻ hơn nhiều so với xử lý trả hàng.' },
  example:'Tháng trước, 800 đơn có 96 đơn trả, tức 12%. Đọc lý do: 60 đơn vì không ghép đôi được hoặc đeo không vừa. Shop in một thẻ ngay trên nắp hộp: "Bước 1: giữ nút 5 giây. Bước 2: thử 3 cỡ nút tai" kèm mã QR tới video. Tháng sau, cũng 800 đơn, số trả còn 44, tỉ lệ 5,5%. Chi phí in thẻ khoảng 1.500 đồng một hộp.',
  takeaway:'Lần dùng đầu là lúc khách kiểm chứng lời hứa; đặt lời giải ngay chỗ họ hay vấp.',
  apply:'Nhớ một món bạn từng mua mà lần đầu dùng bị lúng túng. Nói trong 60 giây: hãng lẽ ra nên đặt lời giải ở đâu.',
  mistakes:['Nghĩ chốt đơn là xong việc của marketing.','Để hướng dẫn trong một tờ giấy dài dưới đáy hộp không ai đọc.'],
  q:[
  { type:'mcq', stem:'Khách trả tai nghe vì "không kết nối được" dù máy không lỗi. Đoán xem gốc vấn đề là gì?',
    options:[{k:'a',t:'Khách mua nhầm loại tai nghe không hợp với điện thoại đang dùng'},{k:'b',t:'Khách vốn đã định trả nên viện một lý do nghe hợp lý để đổi'},
             {k:'c',t:'Lô hàng tháng đó có lỗi phần mềm mà kho chưa phát hiện kịp'},{k:'d',t:'Lần dùng đầu vấp ở bước ghép đôi, hướng dẫn không ở đúng chỗ'}],
    answer:'d', why:{a:'Kiểm tra đã cho thấy máy tương thích; vấn đề là thao tác ghép đôi.',
      b:'Có khách như vậy, nhưng không giải thích một khuôn mẫu lặp lại ở cùng bước.',
      c:'Kiểm tra lại cho thấy máy không lỗi.',
      d:'Đúng. Khách vấp đúng một bước và đổ lỗi cho sản phẩm.'} },
  { type:'mcq', stem:'Với ngân sách nhỏ, bạn chọn sửa gì trước để giảm trả hàng?',
    options:[{k:'a',t:'Viết lại sách hướng dẫn đầy đủ hơn, dày gấp đôi bản hiện tại'},{k:'b',t:'Đặt thẻ hai bước và mã QR video ngay trên nắp hộp'},
             {k:'c',t:'Tăng thời gian đổi trả lên 30 ngày để khách yên tâm hơn'},{k:'d',t:'Đổi sang một mẫu tai nghe khác có kết nối tự động hoàn toàn'}],
    answer:'b', why:{a:'Sách dày hơn vẫn nằm dưới đáy hộp và càng ít người đọc.',
      b:'Đúng. Lời giải đặt đúng chỗ khách nhìn đầu tiên, chi phí rất thấp.',
      c:'Đổi trả dài hơn không sửa việc khách vấp lúc dùng đầu, có khi còn tăng trả.',
      d:'Đổi sản phẩm tốn kém trong khi lỗi nằm ở hướng dẫn.'} },
  { type:'calc', stem:'Sau khi thêm thẻ hướng dẫn, 800 đơn có 44 đơn trả. Tỉ lệ trả hàng mới là bao nhiêu phần trăm?',
    unit:'%', ans:5.5, tol:0.05, wrong:[[94.5,'NHAM_TI_LE_ROI'],[6.5,'NHAM_DIEM_PHAN_TRAM']], errors:['NHAM_TI_LE_ROI','NHAM_DIEM_PHAN_TRAM'],
    steps:['Tỉ lệ trả = số đơn trả ÷ tổng đơn.','44 ÷ 800 = 0,055 = <b>5,5%</b>.'] },
  { type:'calc', stem:'Tỉ lệ trả giảm từ 12% xuống 5,5%. Tỉ lệ này giảm bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:6.5, tol:0.05, wrong:[[54.2,'NHAM_DIEM_PHAN_TRAM'],[52,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Chênh lệch điểm phần trăm = tỉ lệ cũ − tỉ lệ mới.','12% − 5,5% = <b>6,5 điểm %</b>. (Giảm tương đối là 6,5 ÷ 12 ≈ 54%, một con số khác.)'] },
  { type:'mcq', stem:'Một hãng nồi cơm điện muốn khách hài lòng ngay bữa đầu. Việc nào hợp lý nhất?',
    options:[{k:'a',t:'In vạch nước cho từng loại gạo bên trong lòng nồi rõ ràng'},{k:'b',t:'Tặng kèm một túi gạo 5 kg cao cấp để bữa đầu thật ngon'},
             {k:'c',t:'Gửi email cảm ơn kèm mã giảm giá cho lần mua sau của khách'},{k:'d',t:'Làm hộp đựng sang trọng hơn để khách thấy đáng tiền ngay khi mở'}],
    answer:'a', why:{a:'Đúng. Bữa đầu hỏng thường do sai nước; lời giải nằm ngay chỗ khách đổ nước.',
      b:'Gạo ngon không giúp gì nếu khách đổ sai lượng nước.',
      c:'Email sau mua không sửa được bữa đầu bị khê hay nhão.',
      d:'Hộp đẹp tạo cảm xúc lúc mở nhưng không giúp bữa đầu thành công.'} },
  { type:'mcq', stem:'Vì sao lỗi ở lần dùng đầu nguy hiểm hơn lỗi ở lần thứ mười?',
    options:[{k:'a',t:'Vì lần đầu khách thường dùng lúc có khách đến nhà, dễ ngại'},{k:'b',t:'Vì bảo hành chỉ áp dụng cho lỗi xảy ra trong tuần đầu tiên'},
             {k:'c',t:'Vì lần đầu khách chưa có niềm tin tích luỹ để bỏ qua'},{k:'d',t:'Vì lần đầu máy hay yếu hơn do linh kiện chưa chạy quen'}],
    answer:'c', why:{a:'Chi tiết này không phổ biến và không phải lý do chính.',
      b:'Bảo hành thường dài hơn nhiều; đây là hiểu lầm về chính sách.',
      c:'Đúng. Sau nhiều lần dùng tốt khách sẽ châm chước; lần đầu thì một lỗi là đủ để kết luận.',
      d:'Không có cơ sở kỹ thuật chung như vậy; lỗi thường do thao tác.'} },
  { type:'mcq', stem:'Làm sao tìm ra các bước khách hay vấp trong 10 phút đầu dùng sản phẩm?',
    options:[{k:'a',t:'Hỏi đội kỹ thuật xem bước nào trong thiết kế phức tạp nhất'},{k:'b',t:'Đọc lý do trả hàng và câu hỏi gửi tới shop trong tuần đầu'},
             {k:'c',t:'Xem điểm đánh giá trung bình của sản phẩm trên các sàn'},{k:'d',t:'So sách hướng dẫn của mình với sách của các đối thủ lớn'}],
    answer:'b', why:{a:'Đội kỹ thuật quen sản phẩm nên thường không thấy chỗ người mới vấp.',
      b:'Đúng. Lý do trả và tin nhắn hỏi han ghi đúng chỗ khách bị kẹt.',
      c:'Điểm trung bình không chỉ ra bước nào gây vấn đề.',
      d:'Sách của đối thủ không cho biết khách của bạn vấp ở đâu.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kh06-06', skill:'comm', read:'6 phút', t:'Khách vừa mua xong lại thấy lo — bạn nói gì với họ?',
  situation:'Một trung tâm tiếng Anh bán khoá 12 tháng giá 18 triệu. Trong 7 ngày đầu sau khi đóng tiền, nhiều phụ huynh nhắn hỏi "có hoàn tiền không", đọc review trường khác và so sánh lại. Tỉ lệ xin huỷ trong tuần đầu khoảng 8%, cao hơn hẳn các tuần sau.',
  concept:{ name:'Nỗi lo sau mua',
    body:'Sau một quyết định lớn, khách thường thấy bất an: mình chọn đúng chưa, có trả đắt không, lựa chọn kia có tốt hơn không. Nỗi lo này mạnh nhất trong <b>vài ngày đầu</b>, khi chưa có kết quả để tự trấn an. Nếu không ai nói gì, khách tự đi tìm bằng chứng — và dễ gặp bằng chứng ngược. Cách xử lý: chủ động gửi lý do để yên tâm, cho thấy bước tiếp theo cụ thể, và tạo một kết quả nhỏ sớm để khách tự thấy mình chọn đúng.' },
  example:'Trung tâm có 250 học viên mới mỗi tháng, 20 người xin huỷ trong tuần đầu. Họ thêm ba việc: tin nhắn ngày 1 giới thiệu giáo viên và lịch 4 buổi đầu; buổi 2 gửi phụ huynh video con nói câu đầu tiên; ngày 5 gọi hỏi thăm. Tháng sau, cùng 250 học viên, chỉ 9 người xin huỷ. Chi phí chủ yếu là thời gian của nhân viên chăm sóc.',
  takeaway:'Khách vừa chi nhiều tiền thường lo; đừng để họ tự đi tìm câu trả lời.',
  apply:'Nhớ lần bạn mua món đắt tiền. Nói trong 60 giây: trong tuần đầu bạn lo điều gì, và hãng lẽ ra nên nói gì.',
  mistakes:['Im lặng sau khi thu tiền, chờ tới buổi học đầu mới liên lạc.','Tiếp tục gửi quảng cáo bán thêm khi khách còn đang lo chuyện vừa mua.'],
  q:[
  { type:'mcq', stem:'Phụ huynh vừa đóng 18 triệu lại đi đọc review trường khác. Đoán xem vì sao?',
    options:[{k:'a',t:'Họ đang bất an sau quyết định lớn và tìm bằng chứng mình chọn đúng'},{k:'b',t:'Họ định đăng ký thêm một trường nữa để con học song song hai nơi'},
             {k:'c',t:'Họ bị đối thủ nhắm quảng cáo nên tình cờ thấy các bài review'},{k:'d',t:'Họ muốn xin giảm giá nên tìm lý do để thương lượng lại học phí'}],
    answer:'a', why:{a:'Đúng. Đó là nỗi lo sau mua, mạnh nhất trong vài ngày đầu.',
      b:'Học song song hai trung tâm là trường hợp hiếm, không giải thích khuôn mẫu chung.',
      c:'Quảng cáo đối thủ có thể góp phần, nhưng họ chủ động tìm đọc.',
      d:'Có vài người như vậy, nhưng hỏi hoàn tiền và so sánh là dấu hiệu bất an.'} },
  { type:'mcq', stem:'Bạn chỉ làm được một việc trong tuần đầu sau khi thu tiền. Bạn chọn gì?',
    options:[{k:'a',t:'Gửi ưu đãi mua thêm khoá hè để khách thấy được lợi hơn nữa'},{k:'b',t:'Gửi bảng so sánh chi tiết học phí với tất cả trung tâm đối thủ'},
             {k:'c',t:'Chờ buổi học đầu, để chất lượng giảng dạy tự trả lời mọi lo lắng'},{k:'d',t:'Gửi tin ngày đầu: giáo viên của con là ai, 4 buổi đầu học gì'}],
    answer:'d', why:{a:'Bán thêm khi khách đang lo làm tăng cảm giác bị ép.',
      b:'Gửi bảng so sánh lại mở ra cuộc cân nhắc mà khách vừa đóng.',
      c:'Khoảng trống trước buổi đầu chính là lúc nỗi lo lớn nhất.',
      d:'Đúng. Bước tiếp theo cụ thể giúp khách yên tâm rằng quyết định đang được thực hiện.'} },
  { type:'calc', stem:'Trước khi thay đổi: 20 trên 250 học viên xin huỷ tuần đầu. Sau: 9 trên 250. Tỉ lệ huỷ giảm bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:4.4, tol:0.05, wrong:[[55,'NHAM_DIEM_PHAN_TRAM'],[11,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ cũ: 20 ÷ 250 = 8%.','Tỉ lệ mới: 9 ÷ 250 = 3,6%.','Chênh lệch: 8% − 3,6% = <b>4,4 điểm %</b>.'] },
  { type:'mcq', stem:'Vì sao gửi video con nói câu đầu tiên ngay buổi 2 lại có tác dụng?',
    options:[{k:'a',t:'Vì video dễ được phụ huynh chia sẻ lên mạng, giúp quảng cáo miễn phí'},{k:'b',t:'Vì nó là kết quả nhỏ, sớm, cho phụ huynh tự thấy mình chọn đúng'},
             {k:'c',t:'Vì phụ huynh cần video để chứng minh với người thân rằng con có đi học'},{k:'d',t:'Vì video làm phụ huynh ngại xin huỷ khi con đã quen với lớp học'}],
    answer:'b', why:{a:'Có thể được chia sẻ, nhưng tác dụng chính là trấn an người vừa mua.',
      b:'Đúng. Bằng chứng tận mắt giúp xoá nỗi lo tốt hơn lời hứa.',
      c:'Không phải nhu cầu chính của phụ huynh trong tuần đầu.',
      d:'Tác dụng không đến từ việc khiến họ ngại, mà từ việc họ yên tâm thật.'} },
  { type:'mcq', stem:'Một khách vừa mua xe máy 45 triệu nhắn: "Tuần này bên kia giảm 2 triệu, mình có mua hớ không?". Cách trả lời nào tốt nhất?',
    options:[{k:'a',t:'Xin lỗi rồi hoàn ngay 2 triệu để khách không còn gì phàn nàn'},{k:'b',t:'Giải thích rằng giá niêm yết đã cố định nên không thể thay đổi'},
             {k:'c',t:'Ghi nhận nỗi lo, nhắc gói bảo dưỡng khách đã có'},{k:'d',t:'Không trả lời để tránh bị kéo vào thương lượng giá thêm lần nữa'}],
    answer:'c', why:{a:'Hoàn tiền vội tạo tiền lệ và dạy khách rằng cứ hỏi là được trả lại.',
      b:'Đúng về quy định nhưng lạnh lùng, không giải toả nỗi lo.',
      c:'Đúng. Ghi nhận cảm xúc và nhắc giá trị đã có giúp khách thấy mình không mua hớ.',
      d:'Im lặng khiến khách tự kết luận là bị hớ và kể lại cho người khác.'} },
  { type:'mcq', stem:'Nỗi lo sau mua thường mạnh nhất với loại mua nào?',
    options:[{k:'a',t:'Mua hàng giá cao, ít khi mua, khó đổi lại nếu chọn sai'},{k:'b',t:'Mua hàng giá thấp, mua hằng tuần và rất dễ đổi sang hãng khác'},
             {k:'c',t:'Mua hàng giảm giá sâu vì khách lúc nào cũng thấy được lợi'},{k:'d',t:'Mua quà cho người khác vì người mua không phải người dùng'}],
    answer:'a', why:{a:'Đúng. Càng đắt, càng hiếm, càng khó quay lại thì càng lo.',
      b:'Hàng rẻ mua thường xuyên thì chọn sai cũng không sao, ít lo.',
      c:'Giảm giá có thể kèm lo "hàng có vấn đề gì không", nhưng không phải nhóm lo nhất.',
      d:'Mua quà có lo lắng riêng, nhưng không mạnh bằng quyết định đắt tiền cho chính mình.'} },
  { type:'mcq', stem:'Bạn phát hiện đội bán hàng gửi ưu đãi khoá hè ngay ngày thứ 2 sau khi khách đóng tiền. Nên sửa gì?',
    options:[{k:'a',t:'Giữ nguyên vì khách đang có hứng thú nên dễ mua thêm hơn lúc nào hết'},{k:'b',t:'Tăng mức ưu đãi lên để khách thấy lời hơn và bớt lo chuyện học phí'},
             {k:'c',t:'Chuyển ưu đãi sang gửi qua email thay vì nhắn tin để đỡ phiền'},{k:'d',t:'Dời bán thêm tới sau khi khách thấy kết quả, tuần đầu chỉ trấn an'}],
    answer:'d', why:{a:'Khách đang lo, chưa phải đang hào hứng; bán thêm lúc này dễ phản tác dụng.',
      b:'Thêm ưu đãi không giải quyết nỗi lo "chọn đúng chưa".',
      c:'Đổi kênh gửi không đổi bản chất là bán thêm sai thời điểm.',
      d:'Đúng. Trấn an trước, bán thêm sau khi khách đã thấy giá trị.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kh06-07', skill:'measure', read:'7 phút', t:'Làm sao để lần mua thứ hai tự xảy ra?',
  situation:'Một thương hiệu cà phê hạt bán online, mỗi túi 500 g dùng khoảng 25 ngày. Tháng 1 có 1.000 khách mua lần đầu, nhưng tới cuối tháng 3 chỉ 280 người mua lại. Đội marketing định chạy quảng cáo nhắc lại cho cả 1.000 người vào một ngày cố định mỗi tháng.',
  concept:{ name:'Mua lại và thói quen',
    body:'Lần mua thứ hai khó hơn lần đầu nghĩ. Khách không bỏ đi vì ghét, mà vì <b>quên đúng lúc hết hàng</b> và tiện tay mua chỗ khác. Thói quen hình thành khi việc mua lại gắn với một nhịp có sẵn: hết túi, cuối tuần, ngày lương. Việc của bạn là xuất hiện đúng lúc khách sắp hết — dựa vào ngày mua và tốc độ dùng — và làm việc mua lại thật dễ: một chạm là đặt lại đúng món cũ, hoặc đăng ký giao định kỳ.' },
  example:'Túi dùng 25 ngày nên đội đổi lịch: nhắc vào ngày 20 sau đơn, kèm nút "đặt lại đúng món cũ". Ai mua 2 lần liên tiếp được mời giao định kỳ. Với 1.000 khách lần đầu tháng 4, tới cuối tháng 6 có 430 người mua lại, so với 280 trước đó. Nhắc theo ngày cố định mỗi tháng thì với người mua ngày 3, tin nhắn tới muộn cả tuần sau khi họ đã hết cà phê.',
  takeaway:'Khách ít khi bỏ vì ghét; họ quên đúng lúc hết hàng. Nhắc theo nhịp dùng, không theo lịch của bạn.',
  apply:'Chọn một thứ bạn mua đều đặn. Nói trong 60 giây: vì sao bạn cứ mua đúng chỗ đó, và điều gì từng làm bạn đổi.',
  mistakes:['Nhắc mọi khách cùng một ngày thay vì theo nhịp dùng của từng người.','Nghĩ khách không mua lại là vì không thích sản phẩm.'],
  q:[
  { type:'mcq', stem:'Chỉ 28% khách cà phê mua lại. Đoán xem lý do phổ biến nhất là gì?',
    options:[{k:'a',t:'Phần lớn khách thấy cà phê không ngon nên không quay lại nữa'},{k:'b',t:'Giá của thương hiệu cao hơn đối thủ nên khách chuyển đi'},
             {k:'c',t:'Khách chỉ mua thử một lần cho biết, vốn không định dùng lâu dài'},{k:'d',t:'Khách quên đúng lúc hết hàng và tiện tay mua chỗ khác'}],
    answer:'d', why:{a:'Có người không thích, nhưng dữ kiện không cho thấy đánh giá xấu.',
      b:'Giá không đổi giữa lần đầu và lần hai; nếu đắt họ đã không mua lần đầu.',
      c:'Một số là mua thử, nhưng nhiều người uống cà phê hằng ngày vẫn không quay lại.',
      d:'Đúng. Lúc hết hàng mà không có ai nhắc, khách mua chỗ gần tay nhất.'} },
  { type:'mcq', stem:'Đội định nhắc cả 1.000 khách vào ngày 1 mỗi tháng. Bạn sửa gì?',
    options:[{k:'a',t:'Nhắc hai lần mỗi tháng thay vì một lần để khách nhớ tốt hơn'},{k:'b',t:'Nhắc từng khách vào ngày 20 sau đơn, kèm nút đặt lại món cũ'},
             {k:'c',t:'Gửi mã giảm giá 20% cho tất cả để kéo khách quay lại mua'},{k:'d',t:'Giữ ngày 1 vì trùng ngày nhận lương, khách có tiền để mua'}],
    answer:'b', why:{a:'Nhắc dày hơn nhưng vẫn lệch nhịp; khách thấy phiền mà vẫn không đúng lúc.',
      b:'Đúng. Túi dùng 25 ngày; nhắc ngày 20 là lúc khách sắp hết.',
      c:'Giảm giá tốn tiền và không giải quyết chuyện nhắc sai lúc.',
      d:'Lương không trùng với lúc hết cà phê của từng người.'} },
  { type:'calc', stem:'1.000 khách lần đầu, 430 người mua lại sau khi đổi cách nhắc (trước đó là 280). Tỉ lệ mua lại tăng bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:15, tol:0.1, wrong:[[53.6,'NHAM_DIEM_PHAN_TRAM'],[150,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ cũ: 280 ÷ 1.000 = 28%. Tỉ lệ mới: 430 ÷ 1.000 = 43%.','Chênh lệch: 43% − 28% = <b>15 điểm %</b>.'] },
  { type:'mcq', stem:'Một tiệm giặt sấy muốn khách quay lại đều. Nhịp nào hợp lý nhất để gắn thói quen?',
    options:[{k:'a',t:'Giảm giá mạnh vào mỗi dịp lễ lớn trong năm để kéo khách cũ quay trở lại tiệm'},{k:'b',t:'Gửi tin nhắn giới thiệu dịch vụ mới vào mỗi đầu tháng'},
             {k:'c',t:'Gắn với nhịp tuần của khách: nhận đồ tối Chủ nhật, trả sáng thứ Hai'},{k:'d',t:'Chạy quảng cáo tới người ở gần tiệm trong bán kính 2 km'}],
    answer:'c', why:{a:'Lễ chỉ vài lần một năm, không tạo được nhịp đều.',
      b:'Đầu tháng không gắn với lúc khách có đồ bẩn.',
      c:'Đúng. Giặt đồ là việc hằng tuần; gắn vào một khung giờ quen biến nó thành thói quen.',
      d:'Quảng cáo tìm khách mới, không tạo nhịp quay lại.'} },
  { type:'mcq', stem:'Vì sao nút "đặt lại đúng món cũ" lại quan trọng?',
    options:[{k:'a',t:'Vì nó giúp shop bán được món có biên lãi cao hơn món cũ'},{k:'b',t:'Vì khách mua lại thích được gợi ý những món mới lạ hơn'},
             {k:'c',t:'Vì sàn thương mại điện tử yêu cầu shop phải có nút này'},{k:'d',t:'Vì nó bỏ bớt các bước, việc mua lại gần như không tốn công'}],
    answer:'d', why:{a:'Nút này đặt lại đúng món cũ, không đổi sang món khác.',
      b:'Người mua theo thói quen muốn món quen, không phải món lạ.',
      c:'Không có yêu cầu như vậy; đây là lựa chọn thiết kế.',
      d:'Đúng. Càng ít bước, thói quen càng dễ giữ, đối thủ càng khó chen vào.'} },
  { type:'mcq', stem:'Với sữa bột trẻ em (một hộp dùng khoảng 10 ngày), nhắc mua lại lúc nào là hợp lý?',
    options:[{k:'a',t:'Khoảng ngày 7–8 sau đơn, trước khi hộp hết'},{k:'b',t:'Đúng ngày 10, lúc hộp vừa hết để khách cần ngay'},
             {k:'c',t:'Ngày 25 mỗi tháng, sau khi phụ huynh nhận lương'},{k:'d',t:'Ngay sau khi giao hàng để khách nhớ tên thương hiệu'}],
    answer:'a', why:{a:'Đúng. Sữa cho bé không thể thiếu; cần nhắc sớm đủ để giao kịp.',
      b:'Hết rồi mới nhắc thì khách đã ra cửa hàng gần nhà mua.',
      c:'Lịch lương không khớp nhịp 10 ngày của hộp sữa.',
      d:'Vừa giao xong thì khách còn cả hộp, nhắc lúc này vô ích.'} },
  { type:'mcq', stem:'Khách đã mua 5 lần liền nhau. Đâu là bước hợp lý tiếp theo?',
    options:[{k:'a',t:'Dừng nhắc vì khách đã trung thành rồi, không cần làm gì thêm'},{k:'b',t:'Mời đăng ký giao định kỳ để việc mua lại tự diễn ra mỗi kỳ'},
             {k:'c',t:'Tăng giá cho nhóm này vì họ ít nhạy cảm với giá hơn khách mới'},{k:'d',t:'Gửi khảo sát dài 30 câu để hiểu vì sao họ trung thành đến vậy'}],
    answer:'b', why:{a:'Không nhắc nữa thì một lần quên cũng đủ đẩy họ sang chỗ khác.',
      b:'Đúng. Giao định kỳ biến thói quen thành mặc định, bớt rủi ro quên.',
      c:'Tăng giá riêng cho khách quen dễ làm mất lòng tin khi họ phát hiện.',
      d:'Khảo sát dài làm phiền nhóm khách quý nhất.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kh06-08', skill:'insight', read:'7 phút', t:'Bản đồ hành trình dán trên tường — làm sao để nó thật sự có ích?',
  situation:'Một công ty bảo hiểm thuê agency vẽ bản đồ hành trình khách hàng. Kết quả là tấm poster đẹp với 5 giai đoạn "Nhận biết – Cân nhắc – Mua – Dùng – Trung thành", mỗi ô ghi cảm xúc chung chung như "hào hứng", "băn khoăn". Sáu tháng sau, không ai dùng nó để ra quyết định nào.',
  concept:{ name:'Bản đồ hành trình (journey map) dùng được',
    body:'Một bản đồ hành trình có ích khi nó <b>dựa trên khách thật và chỉ ra chỗ cần sửa</b>. Nó nên: chọn một nhóm khách và một mục tiêu cụ thể; liệt kê hành động thật họ làm, ở đâu, mất bao lâu; ghi câu nói nguyên văn từ phỏng vấn; đánh dấu chỗ khách vấp hoặc bỏ đi, có số nếu đo được. Cuối cùng, mỗi điểm gãy phải gắn với một người chịu trách nhiệm và một việc làm thử. Bản đồ không dẫn tới việc cần làm thì chỉ là tranh treo tường.' },
  example:'Công ty vẽ lại cho một nhóm: bố mẹ mua bảo hiểm sức khoẻ cho con dưới 6 tuổi. Phỏng vấn 15 người và xem dữ liệu 600 hồ sơ bắt đầu điền online: 390 hồ sơ dừng ở bước tải giấy khai sinh. Câu nói lặp lại: "Tôi không có bản scan trong máy". Việc làm thử: cho chụp ảnh bằng điện thoại. Người chịu trách nhiệm: đội sản phẩm số, hạn 4 tuần.',
  takeaway:'Bản đồ hành trình tốt kết thúc bằng một danh sách việc cần sửa, không phải một tấm poster.',
  apply:'Vẽ nhanh 5 bước bạn đi khi đặt đồ ăn online. Nói trong 60 giây: bước nào bạn hay bực nhất và nên sửa gì.',
  mistakes:['Vẽ theo khung sẵn có với cảm xúc đoán, không phỏng vấn khách thật.','Gộp mọi nhóm khách vào một bản đồ chung chung.'],
  q:[
  { type:'mcq', stem:'Tấm poster hành trình đẹp nhưng không ai dùng. Đoán xem thiếu gì?',
    options:[{k:'a',t:'Thiếu màu sắc và hình minh hoạ đủ hấp dẫn để mọi người chú ý'},{k:'b',t:'Thiếu dữ liệu khách thật và chỗ cần sửa gắn với người phụ trách'},
             {k:'c',t:'Thiếu thêm giai đoạn "giới thiệu bạn bè" ở cuối hành trình mua'},{k:'d',t:'Thiếu sự phê duyệt của ban giám đốc nên các phòng ban chưa làm theo'}],
    answer:'b', why:{a:'Poster đã đẹp; vấn đề không phải thẩm mỹ.',
      b:'Đúng. Cảm xúc chung chung không chỉ ra việc gì cần làm.',
      c:'Thêm giai đoạn vẫn là khung chung chung, không giải quyết gốc vấn đề.',
      d:'Có phê duyệt thì cũng không biết làm gì với các ô "hào hứng", "băn khoăn".'} },
  { type:'mcq', stem:'Bạn được giao vẽ lại bản đồ. Bạn chọn bắt đầu thế nào?',
    options:[{k:'a',t:'Họp nội bộ cả ngày để các phòng ban cùng điền vào khung 5 giai đoạn'},{k:'b',t:'Vẽ cho mọi loại khách hàng cùng lúc để bản đồ đầy đủ và bao quát'},
             {k:'c',t:'Chọn một nhóm khách cụ thể, phỏng vấn và xem dữ liệu nơi họ dừng'},{k:'d',t:'Thuê agency khác có kinh nghiệm hơn để vẽ lại cho chuyên nghiệp'}],
    answer:'c', why:{a:'Nội bộ điền theo suy đoán dễ lặp lại lỗi cũ.',
      b:'Gộp mọi nhóm làm mờ các điểm gãy riêng của từng nhóm.',
      c:'Đúng. Một nhóm, khách thật, dữ liệu thật mới chỉ ra đúng chỗ cần sửa.',
      d:'Đổi agency không sửa được cách làm thiếu dữ liệu.'} },
  { type:'calc', stem:'600 hồ sơ bắt đầu điền online, 390 hồ sơ dừng ở bước tải giấy khai sinh. Bao nhiêu phần trăm hồ sơ đi qua được bước này?',
    unit:'%', ans:35, tol:0.1, wrong:[[65,'NHAM_TI_LE_ROI'],[210,'NHAM_SO_TUYET_DOI']], errors:['NHAM_TI_LE_ROI','NHAM_SO_TUYET_DOI'],
    steps:['Số hồ sơ đi qua: 600 − 390 = 210.','Tỉ lệ đi qua: 210 ÷ 600 = <b>35%</b>.'] },
  { type:'mcq', stem:'Vì sao nên ghi câu nói nguyên văn của khách vào bản đồ?',
    options:[{k:'a',t:'Nó cho biết lý do thật khách vấp, bằng chính lời của họ'},{k:'b',t:'Để bản đồ trông sinh động hơn khi trình bày trước ban lãnh đạo'},
             {k:'c',t:'Vì quy trình nghiên cứu chuẩn bắt buộc phải có trích dẫn'},{k:'d',t:'Để dùng lại làm câu quảng cáo mà không cần viết nội dung mới'}],
    answer:'a', why:{a:'Đúng. "Không có bản scan" chỉ thẳng tới cách sửa: cho chụp ảnh.',
      b:'Sinh động là phụ; giá trị chính là chỉ ra nguyên nhân.',
      c:'Không phải vì quy trình, mà vì nó giúp tìm cách sửa.',
      d:'Lời khách có thể gợi ý nội dung, nhưng đó không phải mục đích của bản đồ.'} },
  { type:'mcq', stem:'Một điểm gãy đã được tìm ra nhưng không có ai phụ trách. Chuyện gì dễ xảy ra?',
    options:[{k:'a',t:'Các phòng ban sẽ cùng nhau sửa nhanh vì ai cũng thấy vấn đề'},{k:'b',t:'Khách sẽ tự quen với bước khó đó sau một thời gian dùng'},
             {k:'c',t:'Điểm gãy tự biến mất khi công ty nâng cấp phần mềm lớn tiếp'},{k:'d',t:'Ai cũng đồng ý là cần sửa nhưng không ai làm, bản đồ bị bỏ quên'}],
    answer:'d', why:{a:'Việc của mọi người thường thành việc của không ai.',
      b:'Khách mới gặp bước này lần đầu; họ không có cơ hội "quen", họ bỏ đi.',
      c:'Nâng cấp phần mềm không tự nhắm vào điểm gãy nếu không ai đưa vào yêu cầu.',
      d:'Đúng. Mỗi điểm gãy cần một người và một hạn chót.'} },
  { type:'mcq', stem:'Chuỗi phòng khám nha khoa muốn vẽ bản đồ hành trình. Phạm vi nào hợp lý cho bản đầu tiên?',
    options:[{k:'a',t:'Tất cả khách hàng từ trẻ em tới người cao tuổi, mọi dịch vụ'},{k:'b',t:'Người lớn đặt lịch niềng răng lần đầu, từ lúc tìm tới buổi tư vấn'},
             {k:'c',t:'Toàn bộ quy trình nội bộ từ tiếp tân tới kế toán của phòng khám'},{k:'d',t:'Khách của các phòng khám đối thủ để so sánh hành trình với mình'}],
    answer:'b', why:{a:'Quá rộng; mỗi nhóm có hành trình và điểm gãy khác nhau.',
      b:'Đúng. Một nhóm, một mục tiêu, một đoạn hành trình rõ ràng — đủ hẹp để tìm ra việc cần sửa.',
      c:'Đó là quy trình nội bộ, không phải hành trình của khách.',
      d:'Khó tiếp cận khách đối thủ, và chưa hiểu khách của mình thì so sánh chưa có ích.'} },
  { type:'mcq', stem:'Đâu là dấu hiệu một bản đồ hành trình đang được dùng thật?',
    options:[{k:'a',t:'Nó được in khổ lớn và treo ở phòng họp chính của công ty'},{k:'b',t:'Nó được đưa vào tài liệu đào tạo cho toàn bộ nhân viên mới'},
             {k:'c',t:'Có danh sách việc sửa, người phụ trách và kết quả đo lại'},{k:'d',t:'Nó được cập nhật thêm giai đoạn mới mỗi khi có sản phẩm mới'}],
    answer:'c', why:{a:'Treo lên chỉ chứng tỏ nó được trưng bày.',
      b:'Đào tạo có ích nhưng không cho thấy nó dẫn tới thay đổi nào.',
      c:'Đúng. Bản đồ có ích khi nó sinh ra việc làm và kết quả đo được.',
      d:'Thêm giai đoạn cho đầy đủ không đồng nghĩa với việc dùng để quyết định.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:kh06-09', skill:'channel', read:'6 phút', t:'Chai nước 10 nghìn và căn hộ 3 tỉ có chung một hành trình không?',
  situation:'Một agency nhận hai khách hàng cùng lúc: một hãng nước suối đóng chai và một chủ đầu tư căn hộ. Bạn mới vào nghề đề xuất dùng chung một kế hoạch: chạy quảng cáo nhận biết, rồi chạy quảng cáo chuyển đổi, mỗi bên ngân sách chia theo tỉ lệ giống nhau.',
  concept:{ name:'Hành trình mua rẻ và mua đắt',
    body:'Với <b>hàng rẻ, mua thường xuyên</b>, hành trình ngắn vài giây: khách chọn cái quen mắt nhất, dễ lấy nhất. Việc chính là được nhớ tới và có mặt khắp nơi. Với <b>hàng đắt, ít khi mua</b>, hành trình dài hàng tuần hoặc hàng tháng: khách tìm hiểu, hỏi người thân, đi xem tận nơi, nhiều người cùng quyết. Việc chính là cung cấp thông tin, tạo niềm tin và đi cùng khách qua từng bước. Dùng một kế hoạch cho cả hai là bỏ trống chỗ quan trọng nhất của mỗi bên.' },
  example:'Nước suối: 10.000 đồng, khách chọn trong 3 giây ở tủ lạnh cửa hàng tiện lợi — ưu tiên độ phủ điểm bán và nhận diện chai. Căn hộ 3 tỉ: trung bình khách mất khoảng 90 ngày, đi xem nhà mẫu 2–3 lần, cả vợ chồng và bố mẹ góp ý — ưu tiên thông tin pháp lý, bảng tính trả góp, nhân viên theo sát. Với 3 tỉ, vay 70% thì khách cần tự có 900 triệu, nên bảng tính trả góp là điểm chạm quyết định.',
  takeaway:'Hàng rẻ thắng bằng việc có mặt khắp nơi; hàng đắt thắng bằng việc đi cùng khách qua từng bước.',
  apply:'So một món bạn mua dưới 50 nghìn và một món trên 10 triệu. Nói trong 60 giây: bạn đã mất bao lâu và hỏi ai trước khi mua mỗi món.',
  mistakes:['Dùng cùng một khuôn "nhận biết rồi chuyển đổi" cho mọi mức giá.','Đo hàng đắt bằng số đơn ngay sau quảng cáo, như với hàng rẻ.'],
  q:[
  { type:'mcq', stem:'Đoán xem điểm khác lớn nhất giữa hành trình mua nước suối và mua căn hộ là gì?',
    options:[{k:'a',t:'Khách mua căn hộ xem quảng cáo nhiều hơn khách mua nước suối'},{k:'b',t:'Nước suối chỉ bán offline còn căn hộ chủ yếu bán qua kênh online'},
             {k:'c',t:'Độ dài, số người cùng quyết, lượng thông tin cần có'},{k:'d',t:'Khách mua căn hộ ít quan tâm tới giá hơn khách mua nước suối'}],
    answer:'c', why:{a:'Lượng quảng cáo xem được không phải khác biệt cốt lõi.',
      b:'Cả hai đều có online và offline; kênh không phải điểm khác chính.',
      c:'Đúng. Vài giây một mình so với vài tháng cùng cả nhà là hai hành trình khác hẳn.',
      d:'Khách căn hộ rất quan tâm giá, còn tính kỹ cả trả góp.'} },
  { type:'mcq', stem:'Với căn hộ 3 tỉ, bạn ưu tiên đầu tư vào điểm chạm nào?',
    options:[{k:'a',t:'Quảng cáo banner phủ rộng trên nhiều trang báo điện tử lớn'},{k:'b',t:'Bảng tính trả góp, hồ sơ pháp lý rõ và nhân viên theo sát từng khách'},
             {k:'c',t:'Khuyến mãi tặng vàng cho 50 khách đặt cọc đầu tiên trong tuần'},{k:'d',t:'Video ngắn giải trí để tăng lượt xem và độ nhận biết thương hiệu'}],
    answer:'b', why:{a:'Nhận biết cần, nhưng không giúp khách vượt qua các băn khoăn lớn.',
      b:'Đúng. Hành trình dài cần thông tin và niềm tin ở từng bước.',
      c:'Ép chốt nhanh bằng khuyến mãi có thể làm khách nghi ngờ với món đắt.',
      d:'Lượt xem không trả lời được câu hỏi pháp lý và tài chính.'} },
  { type:'calc', stem:'Căn hộ giá 3 tỉ đồng, ngân hàng cho vay 70%. Khách cần tự có bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:900, tol:1, wrong:[[2100,'NHAM_TI_LE_ROI'],[210,'SAI_TINH_TOAN']], errors:['NHAM_TI_LE_ROI','SAI_TINH_TOAN'],
    steps:['Phần tự có = 100% − 70% = 30% giá trị căn hộ.','3.000 triệu × 30% = <b>900 triệu đồng</b>.'] },
  { type:'mcq', stem:'Một hãng snack định in thật nhiều thông tin dinh dưỡng chi tiết lên mặt trước gói. Góp ý nào hợp lý?',
    options:[{k:'a',t:'Hợp lý, vì khách luôn cần đủ thông tin trước khi quyết định mua'},{k:'b',t:'Hợp lý, vì thông tin chi tiết làm thương hiệu trông cao cấp hơn'},
             {k:'c',t:'Nên in thêm bảng so sánh với đối thủ để khách thấy rõ khác biệt'},{k:'d',t:'Mặt trước nên giúp nhận ra và chọn trong vài giây, chi tiết để mặt sau'}],
    answer:'d', why:{a:'Với hàng rẻ mua nhanh, khách không đọc kỹ ở kệ.',
      b:'Cảm giác cao cấp không bù được việc khó nhận ra trong vài giây.',
      c:'Bảng so sánh là cách của hàng đắt, không hợp hành trình vài giây.',
      d:'Đúng. Hành trình ngắn cần dấu hiệu dễ nhận ra, không cần nhiều chữ.'} },
  { type:'mcq', stem:'Vì sao đo quảng cáo căn hộ bằng số hợp đồng trong tuần đầu dễ gây hiểu lầm?',
    options:[{k:'a',t:'Vì hành trình kéo dài khoảng 90 ngày, tuần đầu chưa kịp ra kết quả'},{k:'b',t:'Vì hợp đồng căn hộ thường được ký qua sàn môi giới nên khó đếm'},
             {k:'c',t:'Vì khách mua căn hộ không bao giờ phản hồi quảng cáo trên mạng'},{k:'d',t:'Vì số hợp đồng luôn quá nhỏ để có ý nghĩa thống kê chính xác'}],
    answer:'a', why:{a:'Đúng. Đo quá sớm sẽ kết luận sai là quảng cáo không hiệu quả.',
      b:'Có thể khó đếm, nhưng vấn đề chính là thời điểm đo.',
      c:'Khách có phản hồi, chỉ là phản hồi bằng việc tìm hiểu dần.',
      d:'Số nhỏ là một vấn đề, nhưng lỗi chính là đo lệch với độ dài hành trình.'} },
  { type:'mcq', stem:'Một hãng máy giặt 12 triệu nằm giữa hai cực. Hành trình của khách nên được hiểu thế nào?',
    options:[{k:'a',t:'Như hàng rẻ, vì máy giặt là đồ gia dụng mà gia đình nào cũng có'},{k:'b',t:'Như căn hộ, vì mọi thứ trên 10 triệu đều cần quy trình bán dài'},
             {k:'c',t:'Có so sánh vài tuần, hay bật lên khi máy cũ hỏng gấp'},{k:'d',t:'Không cần hiểu hành trình, chỉ cần giá cạnh tranh là đủ để bán'}],
    answer:'c', why:{a:'12 triệu và dùng nhiều năm thì khách có cân nhắc, không chọn trong vài giây.',
      b:'Không cần mức theo sát như căn hộ; một người thường quyết được.',
      c:'Đúng. Hành trình vừa phải, lại hay bị trigger "máy hỏng" rút ngắn — cần có mặt khi khách gấp.',
      d:'Giá chỉ là một phần; khách vẫn so tính năng, bảo hành, giao lắp.'} },
  { type:'mcq', stem:'Agency chỉ có một bản kế hoạch cho cả nước suối và căn hộ. Bạn nên sửa gì trước?',
    options:[{k:'a',t:'Giữ khuôn chung, chỉ đổi ngân sách lớn hơn cho bên căn hộ'},{k:'b',t:'Chia lại tỉ lệ giữa quảng cáo nhận biết và chuyển đổi cho từng bên'},
             {k:'c',t:'Dùng chung nội dung sáng tạo để tiết kiệm chi phí sản xuất'},{k:'d',t:'Vẽ riêng hành trình của từng bên rồi đặt tiền vào điểm chạm then chốt'}],
    answer:'d', why:{a:'Tăng ngân sách không sửa được việc bỏ trống điểm chạm then chốt.',
      b:'Chỉnh tỉ lệ trong cùng khuôn vẫn bỏ qua bảng trả góp, nhà mẫu, độ phủ điểm bán.',
      c:'Nội dung chung không thể hợp cho cả hai hành trình khác hẳn nhau.',
      d:'Đúng. Hành trình khác nhau thì điểm chạm then chốt khác nhau.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:kh06-10', skill:'measure', read:'7 phút', t:'Khách rơi rụng ở đâu trên đường tới đơn hàng?',
  situation:'Một chuỗi spa mở đặt lịch online. Mỗi tháng có khoảng 2.000 người vào trang dịch vụ, nhưng chỉ khoảng 60 lịch hẹn thành công. Ban giám đốc muốn tăng gấp đôi ngân sách quảng cáo để kéo thêm người vào trang. Bạn được hỏi ý kiến.',
  concept:{ name:'Điểm gãy của hành trình',
    body:'Hành trình thường không hỏng đều; nó <b>gãy ở một vài chỗ</b>. Những chỗ hay gãy: thiếu thông tin quan trọng (giá, thời gian), bước quá rườm rà, phải chờ phản hồi lâu, chuyển kênh bị đứt (từ quảng cáo sang tin nhắn), và lúc khách cần một lời trấn an mà không có. Trước khi đổ thêm người vào đầu, hãy đếm xem ở mỗi bước còn lại bao nhiêu người. Sửa chỗ gãy lớn nhất thường rẻ hơn và hiệu quả hơn kéo thêm người.' },
  example:'Đếm từng bước: 2.000 người xem trang dịch vụ; 800 người bấm "đặt lịch"; 150 người chọn xong giờ; 60 người xác nhận. Từ 800 xuống 150 là chỗ gãy lớn nhất: form bắt đăng ký tài khoản và nhập 9 trường. Chuỗi rút còn tên, số điện thoại, giờ hẹn. Tháng sau, vẫn 2.000 người xem, 800 bấm đặt lịch, 400 chọn xong giờ, 160 xác nhận — gần gấp ba mà không tăng tiền quảng cáo.',
  takeaway:'Đếm người còn lại ở từng bước trước khi kéo thêm người vào đầu hành trình.',
  apply:'Nhớ một lần bạn bỏ dở một đơn hàng online. Nói trong 60 giây: bạn dừng ở bước nào và vì sao.',
  mistakes:['Tăng tiền kéo người vào đầu khi chỗ gãy nằm ở giữa.','Chỉ nhìn con số cuối cùng, không đếm từng bước.'],
  q:[
  { type:'mcq', stem:'2.000 người xem trang, chỉ 60 người đặt lịch. Đoán xem vấn đề lớn nhất thường nằm ở đâu?',
    options:[{k:'a',t:'Quảng cáo kéo sai người nên phần lớn không có nhu cầu làm spa'},{k:'b',t:'Giá dịch vụ spa quá cao so với mặt bằng chung của khu vực'},
             {k:'c',t:'Ở một vài bước cụ thể trong lúc đặt lịch'},{k:'d',t:'Khách chỉ xem cho biết, vốn chưa bao giờ định đặt lịch cả'}],
    answer:'c', why:{a:'Có thể một phần, nhưng 800 người đã bấm đặt lịch — họ có nhu cầu.',
      b:'Nếu giá quá cao, người ta đã không bấm đặt lịch nhiều như vậy.',
      c:'Đúng. Hành trình thường gãy ở vài chỗ; cần đếm từng bước để tìm.',
      d:'800 người chủ động bấm đặt lịch cho thấy nhiều người có ý định thật.'} },
  { type:'mcq', stem:'Ban giám đốc muốn tăng gấp đôi ngân sách quảng cáo. Bạn đề xuất gì?',
    options:[{k:'a',t:'Đồng ý tăng, vì có thêm người vào trang thì số lịch cũng tăng theo'},{k:'b',t:'Đếm người còn lại ở từng bước, sửa chỗ gãy lớn nhất trước khi tăng'},
             {k:'c',t:'Giảm giá dịch vụ 30% trong một tháng để kéo người đặt lịch nhiều hơn'},{k:'d',t:'Chuyển toàn bộ sang đặt lịch qua điện thoại, bỏ hẳn kênh trực tuyến'}],
    answer:'b', why:{a:'Gấp đôi người vào vẫn rơi rụng y như cũ ở chỗ gãy; chi phí mỗi lịch không cải thiện.',
      b:'Đúng. Sửa chỗ gãy thường rẻ hơn và cho kết quả lớn hơn.',
      c:'Giảm giá tốn biên lãi mà không sửa được form rườm rà.',
      d:'Bỏ kênh online là mất 2.000 người xem mỗi tháng.'} },
  { type:'calc', stem:'800 người bấm "đặt lịch" nhưng chỉ 150 người chọn xong giờ. Bao nhiêu phần trăm người bị rơi ở bước này?',
    unit:'%', ans:81.25, tol:0.1, wrong:[[18.75,'NHAM_TI_LE_ROI'],[32.5,'SAI_MAU_SO']], errors:['NHAM_TI_LE_ROI','SAI_MAU_SO'],
    steps:['Số người rơi: 800 − 150 = 650.','Tỉ lệ rơi: 650 ÷ 800 = <b>81,25%</b>.'] },
  { type:'calc', stem:'Sau khi rút gọn form, vẫn 2.000 người xem trang và có 160 lịch xác nhận (trước là 60). Tỉ lệ từ xem trang tới xác nhận lịch bây giờ là bao nhiêu phần trăm?',
    unit:'%', ans:8, tol:0.05, wrong:[[20,'SAI_MAU_SO'],[3,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Tỉ lệ = lịch xác nhận ÷ người xem trang.','160 ÷ 2.000 = <b>8%</b> (trước là 60 ÷ 2.000 = 3%).'] },
  { type:'mcq', stem:'Một shop quần áo thấy nhiều khách bỏ giỏ hàng ngay khi thấy phí giao hàng. Chỗ gãy ở đây là gì?',
    options:[{k:'a',t:'Thông tin quan trọng xuất hiện quá muộn, làm khách thấy bị bất ngờ'},{k:'b',t:'Khách không thích mẫu áo nên tìm cớ để bỏ giỏ hàng giữa chừng'},
             {k:'c',t:'Giá sản phẩm quá cao nên khách cần thêm thời gian để suy nghĩ lại'},{k:'d',t:'Trang web chạy chậm nên khách mất kiên nhẫn ở bước thanh toán'}],
    answer:'a', why:{a:'Đúng. Phí bất ngờ ở bước cuối là chỗ gãy kinh điển; nên báo sớm hoặc gộp vào giá.',
      b:'Khách đã bỏ áo vào giỏ, tức là thích mẫu.',
      c:'Khách bỏ đúng lúc thấy phí giao, không phải lúc thấy giá áo.',
      d:'Không có dữ kiện về tốc độ; thời điểm bỏ trùng với lúc thấy phí.'} },
  { type:'mcq', stem:'Khách nhấn quảng cáo "nhắn tin để được tư vấn" nhưng phải chờ 2 tiếng mới được trả lời. Đây là loại chỗ gãy nào?',
    options:[{k:'a',t:'Thiếu thông tin vì quảng cáo không ghi đủ giá của từng dịch vụ'},{k:'b',t:'Chuyển kênh bị đứt: khách sẵn sàng hỏi nhưng không có ai đón'},
             {k:'c',t:'Quảng cáo nhắm sai tệp khách hàng nên người nhắn không có nhu cầu'},{k:'d',t:'Bước điền form rườm rà khiến khách bực và bỏ ngang giữa chừng'}],
    answer:'b', why:{a:'Thiếu giá có thể là vấn đề khác, nhưng ở đây khách đã nhắn và đang chờ.',
      b:'Đúng. Khách đi từ quảng cáo sang tin nhắn nhưng bị bỏ lửng ở giữa.',
      c:'Người chủ động nhắn hỏi thường có nhu cầu thật.',
      d:'Không có form nào ở đây; khách chỉ nhắn tin.'} },
  { type:'mcq', stem:'Làm sao biết chỗ gãy nào nên sửa trước khi có nhiều chỗ cùng rơi rụng?',
    options:[{k:'a',t:'Sửa bước đầu tiên trước vì mọi thứ phía sau đều phụ thuộc vào nó'},{k:'b',t:'Sửa bước cuối cùng trước vì đó là nơi khách gần tiền nhất rồi'},
             {k:'c',t:'Sửa bước mà đội thiết kế thấy xấu nhất về mặt giao diện và màu sắc hiện tại'},{k:'d',t:'So số người mất ở mỗi bước và độ dễ sửa, chọn chỗ mất nhiều mà sửa được nhanh'}],
    answer:'d', why:{a:'Bước đầu chưa chắc là nơi mất nhiều người nhất.',
      b:'Bước cuối có thể đã ổn; sửa ở đó ít tác dụng.',
      c:'Xấu về giao diện chưa chắc là nơi khách rơi nhiều.',
      d:'Đúng. Ưu tiên theo số người mất và chi phí sửa.'} }
  ] }

] });
